                    'opciones' => '{"opciones": ["Me niego a darle las respuestas directo del cuestionario de la evaluación de seguridad.", "Le paso un resumen rápido de la guía para que ella conteste sola sin darle la clave exacta directamente.", "Le digo al jefe del área que nos dé más tiempo a todos para terminarla bien sin presionarnos.", "Le mando las respuestas rápido porque la prioridad es sacar la operación del piso hoy y mantener la paz."]}',
