    private function resolveNivelOperativoId(string $clave): int
    {
        $id = DB::table('niveles_operativos')
            ->where('clave', $clave)
            ->value('id');

        if ($id === null) {
            throw new \RuntimeException("No se encontró niveles_operativos.clave={$clave} para MiraPreguntasOps400Seeder.");
        }

        return (int) $id;
    }

